create temporary view   ad_item_${grass_region_without_quote}
as
select  case    when item_id is null then -1
                else item_id
        end as item_id
        ,entrance
from    mp_paidads.dwd_advertise_performance_di__reg_s0_live
where   grass_date = ${local_date}
  and   grass_region = ${grass_region}
  and   user_id > 0
  and   entrance in (4, 3, 25, 31, 32)
  and   impression_cnt > 0
group by 1, 2
having  item_id <> -1
;

--sql_divide_splitter--
create temporary view   fx_rate_${grass_region_without_quote}
as
select  grass_date
        ,grass_region
        ,first(exchange_rate) as exchange_rate
from    mp_order.dim_exchange_rate__reg_s0_live
where   grass_date = ${local_date}
  and   grass_region = ${grass_region}
group by 1, 2
;

--sql_divide_splitter--
create temporary view   dwd_advertise_performance_${grass_region_without_quote}
as
select  T1.grass_region
        ,user_id
        ,item_id
        ,search_entrance
        ,expenditure_amt_local / exchange_rate as ads_revenue_usd
from    (
    select  grass_date
            ,grass_region
            ,user_id
            ,item_id
            ,search_entrance
            ,sum(expenditure_amt_local) as expenditure_amt_local
    from    mp_paidads.dwd_advertise_performance_di__reg_s0_live
    where   grass_date = ${local_date}
      and   grass_region = ${grass_region}
      and   user_id > 0
      and   entrance = 1
      and   search_entrance in('homepage_dd_card', 'cart_ymal_card', 'mpp_ymal_card', 'osp_ymal_card', 'pdp_ymal_card')
      and   COALESCE(expenditure_amt_local, 0) > 0
    group by 1, 2, 3, 4, 5
) as T1
left join fx_rate_${grass_region_without_quote} as T2
on      T1.grass_region = T2.grass_region
  and   T1.grass_date = T2.grass_date
;

--sql_divide_splitter--
create temporary view   dws_user_revenue_${grass_region_without_quote}

as
select  T2.user_id
        ,T2.search_entrance
        ,sum(ads_revenue_usd) as dd_to_search_card_ads_revenue_usd
from    (
    select  item_id
    from    ad_item_${grass_region_without_quote}
    where   entrance in (3, 25, 31, 32)
    group by 1
) as T1
join    (
    select  *
    from    dwd_advertise_performance_${grass_region_without_quote}
    where   search_entrance = 'homepage_dd_card'
) as T2
on      T1.item_id = T2.item_id
group by 1, 2
union all
select  T2.user_id
        ,T2.search_entrance
        ,sum(ads_revenue_usd) as ymal_to_search_card_ads_revenue_usd
from    (
    select  item_id
    from    ad_item_${grass_region_without_quote}
    where   entrance in (4)
    group by 1
) as T1
join    (
    select  *
    from    dwd_advertise_performance_${grass_region_without_quote}
    where   search_entrance in ('cart_ymal_card', 'mpp_ymal_card', 'osp_ymal_card', 'pdp_ymal_card')
) as T2
on      T1.item_id = T2.item_id
group by 1, 2
;

--sql_divide_splitter--
create temporary view   user_exp_raw_${grass_region_without_quote} as
select  user_id
        ,exp_group_id
from    srdi_mart.dim_sr_data_warehouse_abtest_user_group
where   grass_region in (${grass_region})
  and   local_date = ${local_date}
  and   is_assignment_log = 1
;

--sql_divide_splitter--
insert overwrite table ${schema}.ads_sr_data_warehouse_homepage_ad_revenue_exp_1d
partition (grass_region = ${grass_region}, local_date = ${local_date})
select  '__ALL__' as exp_group_id
        ,search_entrance
        ,sum(dd_to_search_card_ads_revenue_usd) as dd_to_search_card_ads_revenue_usd
from    dws_user_revenue_${grass_region_without_quote}
group by 1, 2
union all
select  T2.exp_group_id
        ,T1.search_entrance
        ,sum(dd_to_search_card_ads_revenue_usd) as dd_to_search_card_ads_revenue_usd
from    dws_user_revenue_${grass_region_without_quote} as T1
left join user_exp_raw_${grass_region_without_quote} as T2
on      T1.user_id = T2.user_id
group by 1, 2
